.serif{font-family: "Cormorant Garamond", serif; letter-spacing: -0.055em;}
.smoked-glass{background: rgba(255, 255, 255, 0.07); backdrop-filter: blur(15px) contrast(0.95); box-shadow: rgba(255, 255, 255, 0.1) 0px 1px 0px inset, rgba(0, 0, 0, 0.28) 0px 20px 60px;}
.textural-touch{position: relative; overflow: hidden; background: linear-gradient(rgba(255, 255, 255, 0.78), rgba(255, 255, 255, 0.52)), linear-gradient(135deg, rgba(0, 0, 0, 0.04), transparent 45%); border: 1px solid rgba(255, 255, 255, 0.18); color: rgb(43, 35, 25); box-shadow: rgba(255, 255, 255, 0.68) 0px 1px 0px inset, rgba(125, 90, 40, 0.08) 0px -12px 16px inset, rgba(0, 0, 0, 0.25) 0px 20px 40px; transition: transform 0.5s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.5s, background 0.4s;}
.textural-touch::before{content: ""; position: absolute; inset: 0px; background-image: linear-gradient(135deg, rgba(0, 0, 0, 0.08) 0px, rgba(0, 0, 0, 0.08) 1px, transparent 1px, transparent 100%), linear-gradient(45deg, rgba(0, 0, 0, 0.05) 0px, rgba(0, 0, 0, 0.05) 1px, transparent 1px, transparent 100%); opacity: 0.2; mix-blend-mode: multiply; pointer-events: none;}
.textural-touch::after{content: ""; position: absolute; inset: -120%; background: linear-gradient(120deg, transparent 44%, rgba(255, 255, 255, 0.7) 50%, transparent 56%); transform: translateX(-140%) rotate(12deg); animation: 9s ease-in-out 0s infinite normal none running sheen; pointer-events: none; mix-blend-mode: screen;}
.textural-touch:hover{transform: translateY(-4px); box-shadow: rgba(255, 255, 255, 0.74) 0px 1px 0px inset, rgba(125, 90, 40, 0.1) 0px -12px 16px inset, rgba(0, 0, 0, 0.28) 0px 28px 50px;}
.textural-touch:active{transform: translateY(1px) scale(0.99);}
.slat-portal{position: absolute; inset: 0px; overflow: hidden; mask-image: linear-gradient(90deg, black 0px, black 100%);}
.slat-portal::before{content: ""; position: absolute; inset: 0px; background: linear-gradient(rgba(0, 0, 0, 0.06), rgba(0, 0, 0, 0.38)), radial-gradient(circle at 50% 30%, rgba(255, 195, 120, 0.16), transparent 22%); z-index: 2; pointer-events: none;}
.slat-mask::after{content: ""; position: absolute; inset: 0px; background: linear-gradient(rgba(18, 18, 20, 0.1), rgba(18, 18, 20, 0.26)), radial-gradient(circle, transparent 35%, rgba(0, 0, 0, 0.38) 100%); pointer-events: none;}
.hero-video{position: absolute; inset: 0px; width: 100%; height: 100%; object-fit: cover; transform: scale(1.08); filter: saturate(1.08) contrast(1.05) brightness(0.86); will-change: transform;}
.hero{position: relative; min-height: 100svh; overflow: hidden; background: var(--slate);}
.condense{opacity: 0; filter: blur(18px); transform: translateY(24px); animation: 1.2s cubic-bezier(0.16, 1, 0.3, 1) 0s 1 normal forwards running condense;}
.condense:nth-child(3){animation-delay: 0.26s;}
.condense:nth-child(4){animation-delay: 0.38s;}
.top-meter{position: fixed; right: 24px; top: 20px; z-index: 70; display: flex; align-items: center; gap: 14px; padding: 14px 18px; background: rgba(20, 20, 22, 0.46); backdrop-filter: blur(24px) contrast(0.98); border: 1px solid rgba(255, 255, 255, 0.08); box-shadow: rgba(0, 0, 0, 0.22) 0px 18px 50px;}
.meter-bar{width: 180px; height: 8px; background: rgba(255, 255, 255, 0.1); overflow: hidden;}
.meter-bar span{display: block; height: 100%; width: 68%; background: linear-gradient(90deg, rgba(214, 154, 76, 0.8), rgba(255, 223, 180, 0.95));}
.hero-main{position: relative; z-index: 4; min-height: 100svh; display: grid; place-items: center; padding: 120px 24px 48px 140px; text-align: center;}
.hero-inner{max-width: 980px;}
.eyebrow{display: inline-flex; align-items: center; gap: 10px; padding: 10px 16px; border-radius: 999px; background: rgba(255, 255, 255, 0.12); color: white; text-transform: uppercase; letter-spacing: 0.28em; font-size: 10px; backdrop-filter: blur(15px) contrast(0.95); border: 1px solid rgba(255, 255, 255, 0.08);}
.eyebrow span{width: 8px; height: 8px; background: var(--ochre); display: inline-block;}
.title{margin-top: 22px; font-size: clamp(4.8rem, 12vw, 10.6rem); line-height: 0.82; letter-spacing: -0.08em; color: white; text-shadow: rgba(0, 0, 0, 0.3) 0px 16px 38px;}
.slat{display: inline-block; animation: 1.2s cubic-bezier(0.16, 1, 0.3, 1) 0s 1 normal forwards running slatIn; opacity: 0; transform: translateY(42px);}
.slat:nth-child(2){animation-delay: 0.16s;}
.hero-text{margin: 28px auto 0px; max-width: 720px; font-size: 18px; line-height: 1.9; color: rgba(255, 255, 255, 0.82); padding: 20px 24px; border-radius: 1.5rem; background: rgba(255, 255, 255, 0.06); border: 1px solid rgba(255, 255, 255, 0.08); backdrop-filter: blur(15px) contrast(0.95);}
.hero-actions{display: flex; gap: 14px; justify-content: center; flex-wrap: wrap; margin-top: 34px;}
.btn-a{height: 56px; padding-inline: 30px; cursor: pointer; border-width: medium; border-style: none; border-color: currentcolor; border-image: none; color: rgb(44, 35, 23); font-size: 10px; letter-spacing: 0.26em; text-transform: uppercase;}
.btn-b{height: 56px; padding-inline: 30px; cursor: pointer; font-size: 10px; letter-spacing: 0.26em; text-transform: uppercase; color: white; background: rgba(255, 255, 255, 0.06); border: 1px solid rgba(255, 255, 255, 0.12); backdrop-filter: blur(15px) contrast(0.95);}
.panel-space{padding: 120px 0px;}
.shell{width: min(1480px, 100% - 48px); margin: 0px auto;}
.sofa-split{display: grid; grid-template-columns: 1.25fr 0.75fr; min-height: 760px; background: linear-gradient(rgba(255, 255, 255, 0.04), rgba(255, 255, 255, 0.02)); box-shadow: rgba(0, 0, 0, 0.18) 0px 24px 70px; overflow: hidden;}
.ochre-block{background: linear-gradient(rgba(215, 160, 84, 0.92), rgba(180, 125, 61, 0.88)), linear-gradient(135deg, rgba(255, 255, 255, 0.16), transparent 45%); position: relative;}
.charcoal-block{background: linear-gradient(rgba(16, 16, 18, 0.96), rgba(28, 28, 31, 0.92)), linear-gradient(135deg, rgba(255, 255, 255, 0.06), transparent 45%); position: relative;}
.sofa-copy{position: relative; z-index: 2; padding: 76px; display: flex; flex-direction: column; justify-content: center; background: linear-gradient(90deg, rgba(255, 255, 255, 0.08), rgba(255, 255, 255, 0.02)); backdrop-filter: blur(10px);}
.sofa-copy h2, .botanical h2{font-size: clamp(2.8rem, 5.5vw, 6rem); line-height: 0.9; letter-spacing: -0.06em; color: white;}
.sofa-copy p{margin-top: 22px; max-width: 640px; color: rgba(255, 255, 255, 0.86); line-height: 2; font-size: 16px;}
.sofa-label{text-transform: uppercase; letter-spacing: 0.3em; font-size: 10px; color: rgba(255, 255, 255, 0.7);}
.sofa-meta{display: flex; flex-wrap: wrap; gap: 12px; margin-top: 28px;}
.sofa-meta span{padding: 12px 16px; background: rgba(255, 255, 255, 0.1); border: 1px solid rgba(255, 255, 255, 0.08); font-size: 10px; letter-spacing: 0.2em; text-transform: uppercase;}
.accent-pane{display: flex; flex-direction: column; justify-content: space-between; padding: 52px; color: white;}
.accent-pane .small{text-transform: uppercase; letter-spacing: 0.28em; font-size: 10px; color: rgba(255, 255, 255, 0.72);}
.accent-pane .value{font-size: clamp(3rem, 7vw, 6rem); line-height: 0.88; letter-spacing: -0.06em; margin-top: 16px;}
.accessory{padding: 120px 0px;}
.accessory-head{display: flex; align-items: flex-end; justify-content: space-between; gap: 24px; margin-bottom: 28px;}
.accessory-head p{max-width: 440px; color: rgba(255, 255, 255, 0.66); line-height: 1.9;}
.shelf-grid{display: grid; grid-template-columns: repeat(12, 1fr); gap: 18px;}
.shelf{grid-column: span 4; min-height: 260px; padding: 26px; background: linear-gradient(rgba(255, 255, 255, 0.07), rgba(255, 255, 255, 0.03)), linear-gradient(135deg, rgba(255, 255, 255, 0.04), transparent 60%); border: 1px solid rgba(255, 255, 255, 0.08); box-shadow: rgba(0, 0, 0, 0.2) 0px 16px 40px; overflow: hidden; position: relative; opacity: 0; transform: translateY(28px); transition: opacity 0.7s, transform 0.7s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.4s;}
.shelf::before{content: ""; position: absolute; inset: 0px; background: linear-gradient(rgba(255, 255, 255, 0.05), transparent 20%), repeating-linear-gradient(90deg, rgba(255, 255, 255, 0.06) 0px, rgba(255, 255, 255, 0.06) 1px, transparent 1px, transparent 28px); opacity: 0.2; pointer-events: none; mix-blend-mode: screen;}
.shelf.revealed{opacity: 1; transform: translateY(0px);}
.shelf.tall{min-height: 360px;}
.shelf.wide{grid-column: span 8;}
.shelf .tag{text-transform: uppercase; letter-spacing: 0.28em; font-size: 10px; color: rgba(255, 255, 255, 0.58);}
