.botanical-shell::before{content: ""; position: absolute; inset: 0px; background: linear-gradient(135deg, rgba(255, 255, 255, 0.04) 0px, rgba(255, 255, 255, 0.04) 1px, transparent 1px, transparent 100%), linear-gradient(45deg, rgba(255, 255, 255, 0.03) 0px, rgba(255, 255, 255, 0.03) 1px, transparent 1px, transparent 100%); opacity: 0.18; pointer-events: none;}
.botanical-head{max-width: 820px; position: relative; z-index: 1;}
