.contrast-band{margin-top: 40px; display: grid; grid-template-columns: 1fr 1fr; gap: 18px; position: relative; z-index: 1;}
.plant-card{min-height: 240px; padding: 28px; border-radius: 28px; background: linear-gradient(rgba(255, 255, 255, 0.08), rgba(255, 255, 255, 0.03)); border: 1px solid rgba(255, 255, 255, 0.08); backdrop-filter: blur(18px); box-shadow: rgba(0, 0, 0, 0.22) 0px 18px 45px;}
.plant-card h3{margin-top: 16px; font-size: clamp(2rem, 3vw, 3.5rem); line-height: 0.92; letter-spacing: -0.05em; color: white;}
.plant-card p{margin-top: 16px; line-height: 1.85; color: rgba(255, 255, 255, 0.72);}
.foot{padding: 84px 0px 110px;}
.foot-shell{width: min(1480px, 100% - 48px); margin: 0px auto; padding: 44px 46px; background: linear-gradient(rgba(18, 18, 20, 0.98), rgba(10, 10, 12, 0.98)); border: 1px solid rgba(255, 255, 255, 0.06); box-shadow: rgba(0, 0, 0, 0.24) 0px 24px 70px;}
.foot-grid{display: grid; grid-template-columns: 1fr auto; gap: 24px; align-items: end;}
.foot-title{font-size: clamp(2.8rem, 5vw, 5rem); line-height: 0.92; letter-spacing: -0.06em; color: white;}
.foot-copy{margin-top: 18px; max-width: 760px; color: rgba(255, 255, 255, 0.66); line-height: 1.95;}
.foot-tags{display: flex; flex-wrap: wrap; gap: 12px; justify-content: flex-end;}
.foot-tags span{padding: 12px 15px; background: rgba(255, 255, 255, 0.06); border: 1px solid rgba(255, 255, 255, 0.08); text-transform: uppercase; letter-spacing: 0.2em; font-size: 10px; color: rgba(255, 255, 255, 0.75);}
.footer-line{margin: 34px 0px; height: 1px; background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.22), transparent);}
.reveal{opacity: 0; transform: translateY(32px); transition: opacity 0.8s, transform 0.8s cubic-bezier(0.16, 1, 0.3, 1);}
.reveal.in{opacity: 1; transform: translateY(0px);}
@keyframes condense { 
  100% { opacity: 1; filter: blur(0px); transform: translateY(0px); }
}
@keyframes slatIn { 
  100% { opacity: 1; transform: translateY(0px); }
}
@keyframes sheen { 
  100% { transform: translateX(240%) rotate(12deg); }
}
@media (max-width: 1180px){.top-meter{right: 16px;}}
@media (max-width: 1180px){.hero-main{padding: 116px 20px 40px;}}
